}

/**
 * Drops `userId` from every live issue still assigned to them. Archived issues
 * keep their assignee. Each cleared issue publishes one `issue.unassigned`
 * with `actor` as the actor — the path used when a member leaves the org.
 */
export async function unassignLiveIssues(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  assertOrgScope(actor, orgId);

  const assigned = await issueRepo.listLiveIssuesByAssignee(orgId, userId);
  for (const issue of assigned) {
    await assignIssue(actor, {
      orgId,
      issueId: issue.id,
      assigneeId: null,
    });
  }
}

/** Live issues currently assigned to `assigneeId`. Archived rows are left out. */
export async function listLiveIssuesByAssignee(
  orgId: OrgId,
  assigneeId: UserId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.assigneeId, assigneeId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .all();

  return rows.map((row) => toIssue(row));
}

