input.new_string:
    expect(received).toMatchObject({
      orgId: tenant.org.id,
      memberId: target.id,
      userId: tenant.userIds.viewer,
    });
  });

  // Live issues lose the removed member; archived issues keep their assignee.
  it("unassigns every live issue when a member is removed", async () => {
    const tenant = await createTenant("member-remove-unassign", "growth");
    const target = await memberRepo.findMember(tenant.org.id, tenant.userIds.member);
    if (!target) throw new Error("fixture member missing");

    const live = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Live assignment",
        assigneeId: tenant.userIds.member,
      }),
    );
    const archived = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Archived assignment",
        assigneeId: tenant.userIds.member,
      }),
    );
    await issueService.archiveIssue(tenant.actors.owner, tenant.org.id, archived.id);

    const unassigned: Array<{ issueId: string; previousAssigneeId: string; actorId: string | null }> = [];
    const off = subscribe("issue.unassigned", (payload) => {
      unassigned.push({
        issueId: payload.issueId,
        previousAssigneeId: payload.previousAssigneeId,
        actorId: payload.actorId,
      });
    });

    try {
      await memberService.removeMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: target.id,
      });
    } finally {
      off();
    }

    expect(unassigned).toEqual([
      {
        issueId: live.id,
        previousAssigneeId: tenant.userIds.member,
        actorId: tenant.userIds.owner,
      },
    ]);

    const liveAfter = await issueRepo.findIssueById(tenant.org.id, live.id);
    const archivedAfter = await issueRepo.findIssueById(tenant.org.id, archived.id);
    expect(liveAfter?.assigneeId).toBeNull();
    expect(archivedAfter?.assigneeId).toBe(tenant.userIds.member);
  });
});

